arguments.command:
python - <<'PY'
import json,glob,os
for f in glob.glob('factors/*.json'):
 if f.endswith('factor_ensemble.json'): continue
 try:
  d=json.load(open(f)); print(os.path.basename(f), d.get('status'), d.get('factor_id'), d.get('metrics',{}), 'IC',d.get('ic'),d.get('icir'), 'corr',d.get('max_abs_library_correlation'))
 except Exception as e: print(e)
print('ENSEMBLE',open('factors/factor_ensemble.json').read())
PY

